import Foundation
import UIKit

/// National aerial photos for the Satellite map (Filippo, 23 Nov): where a country, German state, Belgian region or
/// South Tyrol publishes its orthophotos as a free, keyless open-data service, the style's `imagery-hd` layer shows
/// them (z13–18) over EOX Sentinel-2 cloudless (`imagery`, 10 m). Everywhere else that layer stays empty and EOX shows.
/// The table and outlines are generated by tools/imagery/imagery.py (App/Resources/Imagery).
enum AerialImagery {
    struct Source: Decodable, Sendable, Equatable {
        let id: String
        let area: String
        let name: String
        /// `{z} {x} {y}`, `{-y}` (TMS rows), `{bbox}` (WMS: the tile in EPSG:3857 metres).
        let url: String
        let attribution: String
        let licence: String
        let licenceURL: String
    }

    final class Catalog: Sendable {
        let sources: [Source]
        let minZoom: Int
        let maxZoom: Int
        private let areas: [String: (shape: RegionShape, bbox: (w: Double, s: Double, e: Double, n: Double))]

        private struct Table: Decodable { let minZoom: Int; let maxZoom: Int; let sources: [Source] }
        private struct Areas: Decodable { let areas: [String: RegionShape] }

        init(sources: Data, areas: Data) throws {
            let t = try JSONDecoder().decode(Table.self, from: sources)
            self.sources = t.sources
            minZoom = t.minZoom
            maxZoom = t.maxZoom
            self.areas = try JSONDecoder().decode(Areas.self, from: areas).areas.mapValues { shape in
                let pts = shape.polygons.flatMap { $0.first ?? [] }
                let lons = pts.map { $0[0] }, lats = pts.map { $0[1] }
                return (shape, (lons.min() ?? 0, lats.min() ?? 0, lons.max() ?? 0, lats.max() ?? 0))
            }
        }

        /// The app's table; empty if the files are missing (the map then shows EOX only).
        static let bundled: Catalog = {
            guard let s = Bundle.main.url(forResource: "aerial-sources", withExtension: "json").flatMap({ try? Data(contentsOf: $0) }),
                  let a = Bundle.main.url(forResource: "aerial-areas", withExtension: "json").flatMap({ try? Data(contentsOf: $0) }),
                  let c = try? Catalog(sources: s, areas: a) else {
                return try! Catalog(sources: Data(#"{"minZoom":13,"maxZoom":18,"sources":[]}"#.utf8), areas: Data(#"{"areas":{}}"#.utf8))
            }
            return c
        }()

        func hasArea(_ id: String) -> Bool { areas[id] != nil }

        /// The service for a tile: the first whose area holds the tile's centre (city-states and regions are listed
        /// before the country or state around them). `nil`: EOX shows.
        func source(z: Int, x: Int, y: Int) -> Source? {
            guard z >= minZoom, z <= maxZoom else { return nil }
            let n = Double(1 << z)
            let lon = (Double(x) + 0.5) / n * 360 - 180
            let lat = atan(sinh(.pi * (1 - 2 * (Double(y) + 0.5) / n))) * 180 / .pi
            let p = LatLon(lat: lat, lon: lon)
            return sources.first { s in
                guard let a = areas[s.area], lon >= a.bbox.w, lon <= a.bbox.e, lat >= a.bbox.s, lat <= a.bbox.n else { return false }
                return a.shape.contains(p)
            }
        }
    }

    /// A source's address for one tile.
    static func url(_ template: String, z: Int, x: Int, y: Int) -> URL? {
        let n = 1 << z
        var s = template.replacingOccurrences(of: "{z}", with: "\(z)").replacingOccurrences(of: "{x}", with: "\(x)")
            .replacingOccurrences(of: "{-y}", with: "\(n - 1 - y)").replacingOccurrences(of: "{y}", with: "\(y)")
        if s.contains("{bbox}") {
            let half = 20_037_508.342789244, size = 2 * half / Double(n)
            let b = [Double(x) * size - half, half - Double(y + 1) * size, Double(x + 1) * size - half, half - Double(y) * size]
            s = s.replacingOccurrences(of: "{bbox}", with: b.map { String(format: "%.2f", $0) }.joined(separator: ","))
        }
        return URL(string: s)
    }

    enum Cleaned: Equatable { case asIs, empty, cleared(Data) }

    /// Services answer outside their coverage (the sea, past a border) with white: an all-white tile is empty (EOX
    /// shows), and a tile across the edge of the coverage loses its white part (served as PNG with those pixels
    /// clear). A tile with a few white pixels (roofs) is served as it came.
    static func dropNoData(_ data: Data) -> Cleaned {
        guard let image = UIImage(data: data)?.cgImage else { return .empty }
        let w = image.width, h = image.height
        var buf = [UInt8](repeating: 0, count: w * h * 4)
        let drawn = buf.withUnsafeMutableBytes { raw -> Bool in
            guard let ctx = CGContext(data: raw.baseAddress, width: w, height: h, bitsPerComponent: 8, bytesPerRow: w * 4,
                                      space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else { return false }
            ctx.draw(image, in: CGRect(x: 0, y: 0, width: w, height: h))
            return true
        }
        guard drawn else { return .asIs }
        var noData = 0, white = 0
        for i in stride(from: 0, to: buf.count, by: 4) {
            if buf[i + 3] < 8 { noData += 1 } else if buf[i] >= whiteLevel, buf[i + 1] >= whiteLevel, buf[i + 2] >= whiteLevel { white += 1 }
        }
        let total = w * h
        if Double(noData + white) >= Double(total) * 0.98 { return .empty }
        if Double(white) <= Double(total) * 0.02 { return .asIs }
        for i in stride(from: 0, to: buf.count, by: 4) where buf[i] >= whiteLevel && buf[i + 1] >= whiteLevel && buf[i + 2] >= whiteLevel {
            buf[i] = 0; buf[i + 1] = 0; buf[i + 2] = 0; buf[i + 3] = 0
        }
        let png = buf.withUnsafeMutableBytes { raw -> Data? in
            guard let ctx = CGContext(data: raw.baseAddress, width: w, height: h, bitsPerComponent: 8, bytesPerRow: w * 4,
                                      space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue),
                  let out = ctx.makeImage() else { return nil }
            return UIImage(cgImage: out).pngData()
        }
        return png.map(Cleaned.cleared) ?? .asIs
    }

    /// JPEG rings the white edge of the coverage with near-white pixels: 245 and up counts as white.
    private static let whiteLevel: UInt8 = 245
}
